#!/usr/bin/env bash
# СУДИТ: hooks/tests/test_backlog_green_side.sh
# probe_D464.sh — проба пункта D464: нога зелёной стороны в
#                 `hooks/tests/test_backlog_green_side.sh` не проверяет КОД ВОЗВРАТА своего
#                 патчера. Драйвер читает только stdout функции (`ENVS=$("green_$ID")`), а
#                 функция кончается `echo` — её код есть код `echo`.
# Результат: вызов `green_<ID>` с НЕИСПРАВНЫМ патчером отличим от вызова с исправным —
#            нога отвечает ненулевым кодом либо не отдаёт каталог-фикстуру.
# Проверка результата: bash hooks/tests/fixtures/probe_D464.sh даёт 0
#
# Коды: 0 — нога различает упавший патчер; 1 — дефект наблюдён (не различает);
#       2 — рамка не собралась (stderr называет, что).
#
# ЧТО ЭТА ПРОБА СУДИТ И ЧЕГО НЕ СУДИТ — названо прямо, потому что это ПРОКСИ.
# Она судит поведение НОГИ (её код возврата и то, отличается ли файл фикстуры от живого),
# а не КОНЕЧНОЕ последствие («свидетель молча сказал PASS»). Последствие при этом настоящее
# и наблюдалось на снятой 19 сентября 2026 ноге `green_D445`: она патчила через `.new` + `mv`,
# патчер умер ассертом, `mv` напечатал ошибку, в фикстуре остался ЖИВОЙ файл, и нога прошла
# PASS. Починка состоит из двух половин — отказ у ноги (`apply_patch`) и чтение её кода у
# драйвера, — и вес их разный: первая ДОСТАТОЧНА (с подменённым патчером свидетель называет
# FAIL у всех семи ног), вторая разделяет каналы «нога не собралась» и «Проверка красна».
# Утверждение «без второй половины починка мнима» я написал и снял: скептик показал прямым
# замером, что ложного зелёного без неё нет — пустое окружение есть то самое условие, при
# котором отрицательный контроль T0 требует красноты «Проверки», и она красна у 11 из 11.
#
# Носитель для суда выбран `green_D438`: он патчит файл НА МЕСТЕ (src == dst), и на падении
# патчера в фикстуре остаётся живой файл — ближайшее к устройству снятой `green_D445`.
# Тело ноги ВЫРЕЗАЕТСЯ из живого свидетеля и исполняется как есть; вырезание — деталь рамки
# (не удалось — код 2), а не предмет суда.
set -uo pipefail
ROOT="$(cd "$(dirname "$0")/../../.." && pwd -P)"
MECH="${CLAUDSOUL_REPO:-$ROOT}"
WITNESS="$MECH/hooks/tests/test_backlog_green_side.sh"
[ -f "$WITNESS" ] || { echo "probe_D464: нет $WITNESS" >&2; exit 2; }
command -v python3 >/dev/null 2>&1 || { echo "probe_D464: нет python3" >&2; exit 2; }
T=$(cd "$(mktemp -d)" && pwd -P) || { echo "probe_D464: нет временного каталога" >&2; exit 2; }
trap 'rm -rf "$T"' EXIT

# Песочница притворяется репозиторием ровно в том, что нужно ноге D438: три файла hooks/ и
# каталог фикстур со СВОИМ, неисправным патчером. Живое дерево только читается.
mkdir -p "$T/repo/hooks/tests/fixtures" "$T/tmp" || { echo "probe_D464: песочница не собралась" >&2; exit 2; }
for f in backlog-lib.sh command-scope-lib.sh backlog-vanish-check.sh; do
    cp "$MECH/hooks/$f" "$T/repo/hooks/$f" || { echo "probe_D464: нет hooks/$f — рамка не собралась" >&2; exit 2; }
done
# НОГА ВЫБИРАЕТСЯ ПО СВОЙСТВУ, А НЕ ПО ИМЕНИ (22 сентября 2026, находка волны разбора).
# Здесь стояло имя `green_D438` литералом — и в приборе, и в свидетеле, на каждом конце связи
# отдельно (корень R1). Ногу сняли штатно, как снимают любую при закрытии её пункта, и проба
# умерла молча: код 2 «тело не вырезано», то есть закрытие пункта D464 с тех пор не
# охранялось НИЧЕМ. Нашла это волна разбора D474, а не сторож.
# Теперь носитель выводится из свидетеля: ПЕРВАЯ нога, зовущая владельца вызова патчера
# `apply_patch`. Свойство это и есть предмет пробы — «нога не проверяет код своего патчера».
# Годится не всякая нога с `apply_patch`: у снятого пункта нога остаётся в свидетеле, а её
# патчер удаляют — так живёт `green_D470` (пункт D470 закрыт знаком отмены, патчера нет).
# Такая нога мертва: драйвер её не зовёт, и судить по ней значило бы судить труп. Потому
# условие двойное — зовёт apply_patch И её патчер ЕСТЬ на диске.
LEG=""; PATCHER=""
for _n in $(grep -oE '^green_D[0-9]+\(\)' "$WITNESS" 2>/dev/null | tr -d '()'); do
    _line=$(grep "^${_n}()" "$WITNESS")
    case "$_line" in *apply_patch*) ;; *) continue ;; esac
    _p=$(grep -oE "fixtures/green_D[0-9]+\.py" <<< "$_line" | head -1)
    _p="${_p##*/}"
    [ -n "$_p" ] && [ -f "$MECH/hooks/tests/fixtures/$_p" ] || continue
    LEG="$_n"; PATCHER="$_p"; break
done
[ -n "$LEG" ] || { echo "probe_D464: в свидетеле нет живой ноги с apply_patch и существующим патчером — рамка не собралась" >&2; exit 2; }
printf '#!/usr/bin/env python3\nimport sys\nsys.exit(1)\n' > "$T/repo/hooks/tests/fixtures/$PATCHER"

BODY="$T/body.sh"
# Вырезается ВСЁ, от чего нога зависит: mkfix, владелец вызова патчера apply_patch (если он
# в свидетеле есть — до починки D464 его не было) и само тело ноги. Заглушки вместо них
# ставить нельзя: тогда проба судила бы не свидетеля, а свою подделку.
# Диапазон кончается на ЛЮБОЙ следующей ноге, а не на имени конкретного соседа. Прежняя
# редакция резала до `^green_D439()`, и снятие этой ноги — событие штатное, сегодня оно
# случилось четырежды — уводило диапазон до конца файла: вырезалось 153 строки вместо 10,
# включая цикл драйвера, и он ИСПОЛНЯЛСЯ при `. "$BODY"`. Найдено скептиком прогоном.
sed -n "/^mkfix()/p; /^apply_patch()/,/^}/p; /^${LEG}()/,/^green_D[0-9]*()/p" "$WITNESS" \
    | sed "/^green_D[0-9]*()/{ /^${LEG}()/!d; }" > "$BODY"
grep -q "^${LEG}()" "$BODY" || { echo "probe_D464: тело $LEG не вырезано из свидетеля — рамка не собралась" >&2; exit 2; }
grep -q '^mkfix()' "$BODY" || { echo "probe_D464: mkfix не вырезан из свидетеля — рамка не собралась" >&2; exit 2; }
grep -q '^apply_patch()' "$BODY" || { echo "probe_D464: apply_patch не вырезан из свидетеля — рамка не собралась" >&2; exit 2; }
# Сторож убегания: тело ноги — десяток строк. Больше двадцати либо попавший сюда драйвер
# значат, что диапазон снова уехал, и это ОТКАЗ РАМКИ, а не вердикт о дефекте.
# ПОРОГ ВЫВОДИТСЯ ИЗ СВИДЕТЕЛЯ, А НЕ СТОИТ ЧИСЛОМ (22 сентября 2026). Константа 30 была
# подогнана под короткую ногу `green_D438`; когда выбор ноги стал выводиться по свойству,
# первой живой оказалась `green_D446` — она копирует дерево и заводит репозиторий, её тело
# 33 строки, и честная рамка объявлялась уехавшей. Длина ноги — свойство свидетеля, и
# спрашивается она у него: сколько строк от её заголовка до следующей ноги, плюс запас на
# `mkfix` и `apply_patch`, которые вырезаются вместе с ней.
_LEG_N=$(awk -v n="^${LEG}\\(\\)" '$0 ~ n {c=1; next} c && /^green_D[0-9]*\(\)/ {exit} c {c++} END {print c+0}' "$WITNESS")
[ "${_LEG_N:-0}" -gt 0 ] || _LEG_N=10
_BODY_MAX=$((_LEG_N + 25))
_BODY_N=$(wc -l < "$BODY")
[ "$_BODY_N" -le "$_BODY_MAX" ] || { echo "probe_D464: вырезано $_BODY_N строк при пределе $_BODY_MAX (нога $LEG — $_LEG_N) — диапазон уехал, рамка не собралась" >&2; exit 2; }
grep -q 'run_check\|backlog_open_items' "$BODY" && { echo "probe_D464: в вырезанное тело попал драйвер свидетеля — рамка не собралась" >&2; exit 2; }

# ПУТЬ ПАТЧИМОГО ФАЙЛА НЕ ЗНАЕТСЯ, А ВЫВОДИТСЯ ИЗ СРАВНЕНИЯ (23 сентября 2026, D476).
# Здесь стоял литерал `hooks/backlog-vanish-check.sh` — тот же корень R1, что был с ИМЕНЕМ
# ноги: имя вывели 22 сентября 2026, путь оставили, и проба продолжала знать подсудимого
# наизусть. Как только выбор ноги стал выводиться по свойству, первой живой оказалась
# `green_D446`, патчащая ROOTS.md, — и контроль честно сказал «нога не положила файл по
# ожидаемому пути», то есть рамка не собралась ни на одной живой ноге.
# Предмет пробы — «патч ВИДЕН сравнением», а не «изменился вот этот файл». Потому сверяется
# ВЕСЬ каталог, отданный ногой, против живого дерева: хоть один отличающийся файл и есть
# доказательство, что патчер сработал. Имя при этом не нужно никому.
# _differs <каталог фикстуры> → 0 если хоть один файл отличается от живого дерева
# Конвейер здесь ЗАПРЕЩЁН: `find | while | grep -q` под `pipefail` отвечает 141 — grep
# выходит на первом совпадении и роняет производителя сигналом, то есть УСПЕХ читается как
# провал. Поймано своим же прогоном 23 сентября 2026: проба сказала «живой патчер не изменил
# ни одного файла», хотя ROOTS.md отличался. Тот самый дефект, о котором предупреждает страж
# `pipefail-grep-q-notice`, и второй мой носитель за сессию. Вывод собирается в переменную.
_differs() {
    _d="${1%/}"
    [ -d "$_d" ] || return 1
    _found=""
    _list=$(find "$_d" -type f -print 2>/dev/null)
    while IFS= read -r _f; do
        [ -n "$_f" ] || continue
        _rel="${_f#"$_d"/}"
        case "$_rel" in .git/*|*/.git/*) continue ;; esac
        # СЧИТАЕТСЯ ТОЛЬКО ИЗМЕНЁННЫЙ ФАЙЛ, а не новый (23 сентября 2026, поймано мутацией).
        # Первая редакция засчитывала различием и файл, которого нет в живом дереве. Но нога
        # кладёт патч в отдельный `ROOTS.patched.md`, и он появляется ДАЖЕ когда патчер упал:
        # контроль был зелен на мутанте с выключенным сравнением, то есть доказательство
        # держалось на побочном файле, а не на работе патчера.
        [ -f "$MECH/$_rel" ] || continue
        if ! cmp -s "$_f" "$MECH/$_rel"; then _found="diff"; break; fi
    done <<EOF
$_list
EOF
    [ -n "$_found" ]
}

# Контроль рамки: с ИСПРАВНЫМ патчером (живым) нога обязана отработать и отдать каталог,
# и файл в нём обязан ОТЛИЧАТЬСЯ от живого — иначе различать нечем.
OK_OUT=$( REPO="$MECH" TMP="$T/tmp-ok" bash -c 'mkdir -p "$TMP"; . "'"$BODY"'"; '"$LEG" 2>"$T/ok.err" ); OK_RC=$?
[ "$OK_RC" = 0 ] || { echo "probe_D464: контроль — нога с живым патчером отвечает $OK_RC: $(head -1 "$T/ok.err")" >&2; exit 2; }
grep -q 'CLAUDSOUL_REPO=' <<< "$OK_OUT" || { echo "probe_D464: контроль — нога не отдала каталог-фикстуру: [$OK_OUT]" >&2; exit 2; }
OK_DIR=${OK_OUT#CLAUDSOUL_REPO=}
# ФАЙЛ ОБЯЗАН СУЩЕСТВОВАТЬ, и это проверяется ОТДЕЛЬНОЙ строкой. `cmp -s` на отсутствующем
# файле отвечает 2, а не 0, поэтому клауза ниже его пропускала: нога, кладущая патч по
# другому пути (обычный рефакторинг), проходила контроль, а суд читал «файла нет» как
# «нога различила упавший патчер» — ложный зелёный при полностью живом дефекте. Найдено
# скептиком прогоном: путь назначения изменён, устройство ноги возвращено к HEAD, rc=0.
_differs "$OK_DIR" || {
    echo "probe_D464: контроль — живой патчер не изменил НИ ОДНОГО файла фикстуры ($OK_DIR), различать нечем" >&2
    exit 2; }

# Суд: тот же вызов с НЕИСПРАВНЫМ патчером (выходит кодом 1, ничего не пишет).
BAD_OUT=$( REPO="$T/repo" TMP="$T/tmp-bad" bash -c 'mkdir -p "$TMP"; . "'"$BODY"'"; '"$LEG" 2>"$T/bad.err" ); BAD_RC=$?
if [ "$BAD_RC" != 0 ]; then
    exit 0
fi
BAD_DIR=${BAD_OUT#CLAUDSOUL_REPO=}
if ! grep -q 'CLAUDSOUL_REPO=' <<< "$BAD_OUT" ; then
    exit 0
fi
# «Каталог отдан, а файла в нём нет» — законный отказ ноги ТОЛЬКО потому, что контроль выше
# уже доказал: с живым патчером файл по этому пути есть. Без того доказательства тот же вид
# означал бы «проба смотрит не туда», и читать его как починку нельзя.
if ! _differs "$BAD_DIR"; then
    echo "probe_D464: дефект — патчер упал (код 1), нога ответила 0 и отдала фикстуру, НЕОТЛИЧИМУЮ от живого дерева: $BAD_DIR" >&2
    exit 1
fi
echo "probe_D464: патчер упал, но файл фикстуры отличается от живого — непредвиденный вид, судить нечем" >&2
exit 2
